contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, bool freeze) public payable {
        require(target != address(0));
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;
        bool frozenNow = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, false); if (__ESBMC_reverted()) return;
        bool frozenAfter = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        assert(frozenNow == freeze && !frozenAfter
            && c.balanceOf(address(this)) == balBefore
            && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

